window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cc91361bde621bd6"]={"versions": [{"id": "FIG-cc91361bde621bd6", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Feature-Diagramm / Feature-Baum nach FODA-Notation (Feature-Oriented Domain Analysis) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>).\n</li><li><strong>Architektur-Kontext:</strong> Plattformübergreifende Variabilitäts- und Anforderungsmodellierung auf Foundation-Ebene. Das Diagramm standardisiert die funktionale Dekomposition des Busses <code>CAN</code> (<code>FO_TR_FEAT_00157</code>) in verpflichtende und optionale Feature-Zweige für Classic Platform (CP) und Adaptive Platform (AP).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Root-Feature:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00157</code> (<code>CAN</code>): Übergreifendes System-Feature für die Controller-Area-Network-Kommunikation.\n</li></ul>\n</li><li><strong>Sub-Features &amp; Beziehungssemantik:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00158</code> (<code>CAN_Physical_Layer</code>):\n<ul class=\"fig-list\"><li><strong>Beziehungstyp:</strong> Mandatory Sub-Feature (gekennzeichnet durch den ausgefüllten Kreis an der Kante).\n</li><li><strong>Bedeutung:</strong> Jede Instanziierung oder Implementierung des Features <code>FO_TR_FEAT_00157</code> erfordert zwingend die physikalische Schicht (Transceiver-Ansteuerung, Bit-Timing, Signalpegel-Definition).\n</li></ul>\n</li><li><code>FO_TR_FEAT_00163</code> (<code>CAN_Protocols</code>):\n<ul class=\"fig-list\"><li><strong>Beziehungstyp:</strong> Optional Sub-Feature (gekennzeichnet durch den hohlen Kreis an der Kante).\n</li><li><strong>Bedeutung:</strong> Spezifische höherwertige CAN-Protokolle (z. B. Transportprotokolle wie CanTp, Netzwerkmanagement oder diagnostische Protokollstacks) sind optional und werden bedarfsgerecht selektiert.\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Variabilitäts- und Metamodell.\n</li><li><strong>Wirkzeitpunkt:</strong> Das Diagramm beschreibt keine Laufzeit-Dynamik, sondern statische Bindungs- und Ableitungsregeln zur Systemdefinitions- und Konfigurationszeit (System Template / Ecuc-Generierung).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW- &amp; MCAL-Konfiguration (Classic AUTOSAR):</strong>\n<ul class=\"fig-list\"><li>Wird ein CAN-Cluster im System-Extract deklariert, muss mindestens der Hardwareschnittstellen-Pfad (<code>CAN_Physical_Layer</code>: MCAL-Treiber <code>Can</code>, Hardware-Abstraktion <code>CanIf</code> sowie ggf. <code>CanTrcv</code>) abgebildet werden.\n</li><li>Protokollerweiterungen unter <code>CAN_Protocols</code> (z. B. <code>CanTp</code>, <code>CanNm</code>) können bei reiner zyklischer Signalübertragung (Layer 2 Frames bis 8 Byte bzw. 64 Byte bei CAN FD) entfallen, um Memory-Footprint (ROM/RAM) und OS-Task-Last zu minimieren.\n</li></ul>\n</li><li><strong>Adaptive Platform:</strong>\n<ul class=\"fig-list\"><li>Signalisiert die Notwendigkeit des Hardware-Zugriffs (z. B. SocketCAN / Kernel-Treiber für den Physical Layer), während <code>CAN_Protocols</code> als optionale Middleware- bzw. Binding-Komponente in <code>ara::com</code> oder separaten Dämonen realisiert wird.\n</li></ul>\n</li></ul>"}, {"id": "FIG-cb7e2b0ef814f29b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Feature-Diagramm / Feature-Baum nach FODA-Notation (Feature-Oriented Domain Analysis) gemäß AUTOSAR Foundation (<code>AUTOSAR_FO_TR_Features</code>).\n</li><li><strong>Architektur-Kontext:</strong> Plattformübergreifende Variabilitäts- und Anforderungsmodellierung auf Foundation-Ebene. Das Diagramm standardisiert die funktionale Dekomposition des Busses <code>CAN</code> (<code>FO_TR_FEAT_00157</code>) in verpflichtende und optionale Feature-Zweige für Classic Platform (CP) und Adaptive Platform (AP).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Root-Feature:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00157</code> (<code>CAN</code>): Übergreifendes System-Feature für die Controller-Area-Network-Kommunikation.\n</li></ul>\n</li><li><strong>Sub-Features &amp; Beziehungssemantik:</strong>\n<ul class=\"fig-list\"><li><code>FO_TR_FEAT_00158</code> (<code>CAN_Physical_Layer</code>):\n<ul class=\"fig-list\"><li><strong>Beziehungstyp:</strong> Mandatory Sub-Feature (gekennzeichnet durch den ausgefüllten Kreis an der Kante).\n</li><li><strong>Bedeutung:</strong> Jede Instanziierung oder Implementierung des Features <code>FO_TR_FEAT_00157</code> erfordert zwingend die physikalische Schicht (Transceiver-Ansteuerung, Bit-Timing, Signalpegel-Definition).\n</li></ul>\n</li><li><code>FO_TR_FEAT_00163</code> (<code>CAN_Protocols</code>):\n<ul class=\"fig-list\"><li><strong>Beziehungstyp:</strong> Optional Sub-Feature (gekennzeichnet durch den hohlen Kreis an der Kante).\n</li><li><strong>Bedeutung:</strong> Spezifische höherwertige CAN-Protokolle (z. B. Transportprotokolle wie CanTp, Netzwerkmanagement oder diagnostische Protokollstacks) sind optional und werden bedarfsgerecht selektiert.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Nicht zutreffend:</strong> Statisches Variabilitäts- und Metamodell.\n</li><li><strong>Wirkzeitpunkt:</strong> Das Diagramm beschreibt keine Laufzeit-Dynamik, sondern statische Bindungs- und Ableitungsregeln zur Systemdefinitions- und Konfigurationszeit (System Template / Ecuc-Generierung).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW- &amp; MCAL-Konfiguration (Classic AUTOSAR):</strong>\n<ul class=\"fig-list\"><li>Wird ein CAN-Cluster im System-Extract deklariert, muss mindestens der Hardwareschnittstellen-Pfad (<code>CAN_Physical_Layer</code>: MCAL-Treiber <code>Can</code>, Hardware-Abstraktion <code>CanIf</code> sowie ggf. <code>CanTrcv</code>) abgebildet werden.\n</li><li>Protokollerweiterungen unter <code>CAN_Protocols</code> (z. B. <code>CanTp</code>, <code>CanNm</code>) können bei reiner zyklischer Signalübertragung (Layer 2 Frames bis 8 Byte bzw. 64 Byte bei CAN FD) entfallen, um Memory-Footprint (ROM/RAM) und OS-Task-Last zu minimieren.\n</li></ul>\n</li><li><strong>Adaptive Platform:</strong>\n<ul class=\"fig-list\"><li>Signalisiert die Notwendigkeit des Hardware-Zugriffs (z. B. SocketCAN / Kernel-Treiber für den Physical Layer), während <code>CAN_Protocols</code> als optionale Middleware- bzw. Binding-Komponente in <code>ara::com</code> oder separaten Dämonen realisiert wird.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-cc91361bde621bd6", "to": "FIG-cb7e2b0ef814f29b", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
